def read_ints():
    return list(map(int, input().split()))

def main():
    n, m = read_ints()
    degree = [0] * (n + 1)
    for _ in range(m):
        x, y = read_ints()
        degree[x] += 1
        degree[y] += 1

    odd_count = sum(1 for d in degree if d % 2 == 1)

    if odd_count == 0:
        print(0)
    else:
        print(odd_count // 2)

if __name__ == "__main__":
